const routeUrls={catalog:'/',landing:'/',menu:'/cardapio/',store:'/pedidos/',admin:'/gerenciamento/',waiter:'/garcom/',proposal:'/proposta/',reviews:'/avaliar/',table:'/pedidos/?mesa=04'};
function setView(v){location.href=routeUrls[v]||'/'}
function render(){app.innerHTML=({catalog:catalogView,menu:menuView,store:ordersView,admin:adminView,waiter:waiterView,proposal:proposalView,reviews:reviewsView})[view]();bindView();initInteractive();if(routeApp==='catalog')initMotion();}
function bindView(){bindProductActions();document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;updateProducts()});const search=document.getElementById('menu-search');if(search)search.oninput=()=>{query=search.value;updateProducts()};document.querySelectorAll('[data-cart]').forEach(b=>b.onclick=openCart);document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>openTracking(Number(b.dataset.track)));document.querySelectorAll('[data-advance]').forEach(b=>b.onclick=()=>advance(Number(b.dataset.advance)));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{orderFilter=b.dataset.filter;render()});const as=document.getElementById('admin-search');if(as)as.oninput=()=>{adminQuery=as.value;document.getElementById('board').innerHTML=board();bindAdvance();bindReceiptButtons()};const reset=document.getElementById('reset');if(reset)reset.onclick=resetConfirm;const newOrder=document.getElementById('new-order');if(newOrder)newOrder.onclick=()=>setView('store');document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>orderReceipt(Number(b.dataset.receipt)));document.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>callTable(b.dataset.call));document.querySelectorAll('[data-waiter-table]').forEach(b=>b.onclick=()=>{tableNumber=Number(b.dataset.waiterTable);render()});document.querySelectorAll('[data-waiter-category]').forEach(b=>b.onclick=()=>{waiterCategory=b.dataset.waiterCategory;render()});document.querySelectorAll('[data-waiter-add]').forEach(b=>b.onclick=()=>waiterProduct(b.dataset.waiterAdd));document.querySelectorAll('[data-draft-change]').forEach(b=>b.onclick=()=>{const xs=tableDraft(),x=xs.find(x=>x.key===Number(b.dataset.key));if(!x)return;x.quantity=Math.min(20,x.quantity+Number(b.dataset.draftChange));state.waiterDrafts[tableNumber]=xs.filter(x=>x.quantity>0);save();render()});const note=document.getElementById('waiter-note');if(note)note.oninput=()=>{state.waiterNotes[tableNumber]=note.value;save()};const send=document.getElementById('waiter-send');if(send)send.onclick=sendTableDraft;const account=document.getElementById('waiter-account');if(account)account.onclick=()=>tableReceipt(tableNumber);document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>{state.calls=state.calls.filter(c=>c.id!==Number(b.dataset.resolve));save();render();toast('Chamado marcado como atendido')});document.querySelectorAll('[data-select-category]').forEach(a=>a.onclick=()=>{if(document.getElementById('products')){category=a.dataset.selectCategory;updateProducts()}});bindProposal();}
function bindReceiptButtons(){document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>orderReceipt(Number(b.dataset.receipt)))}
const baseBindAdvance=bindAdvance;bindAdvance=function(){baseBindAdvance();bindReceiptButtons()};
const baseWaiterView=waiterView;waiterView=function(){const html=baseWaiterView();return html.replace('<div class="waiter-layout">',`<section class="panel waiter-calls"><div class="panel-top"><h3>Chamados do salão</h3><span>${state.calls.length} pendentes</span></div>${state.calls.length?state.calls.map(c=>`<div class="call-item"><span class="call-icon">${icon('bell')}</span><div class="call-text"><strong>Mesa ${String(c.table).padStart(2,'0')}</strong><small>${esc(c.reason)}</small></div><button class="outline" data-resolve="${c.id}">Atendido ${icon('check')}</button></div>`).join(''):'<p class="small muted">Nenhum chamado pendente.</p>'}</section><div class="waiter-layout">`)};
document.addEventListener('keydown',e=>{if(!overlay.children.length)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const els=[...overlay.querySelectorAll('button:not(:disabled),input,select,textarea,[href]')].filter(el=>el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===overlay.querySelector('.modal'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===overlay.querySelector('.modal'))){e.preventDefault();first.focus()}}});
window.addEventListener('storage',e=>{if(e.key==='eneias-demo-v4'){try{const fresh=JSON.parse(e.newValue);if(fresh){state=fresh;const tracking=overlay.querySelector('[data-tracking]')?.dataset.tracking;if(tracking)openTracking(Number(tracking));else if(!overlay.children.length)render()}}catch{}}});
if(routeApp==='menu'&&categories.includes(params.get('categoria')))category=params.get('categoria');
render();
if(location.hash){try{const anchor=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(anchor)requestAnimationFrame(()=>anchor.scrollIntoView({behavior:'instant',block:'start'}))}catch{}}
if(routeApp==='orders'&&params.get('item')){const item=products.find(p=>p.id===params.get('item'));if(item)openProduct(item.id)}
